(async () => {
  const scene = window.__lastJackpot.renderer.scene;
  const walls = scene.meshes.filter(m => m.name.startsWith('hotel walls'));
  const report = walls.map(m => ({name:m.name, vertices:m.getTotalVertices(), triangles:m.getTotalIndices()/3, finite:m.getVerticesData('position').every(Number.isFinite), lit:scene.lights.filter(l=>l.name.startsWith('hotel light')&&l.includedOnlyMeshes.includes(m)).length}));
  if(report.length!==6||report.some(m=>!m.finite||!m.lit)) throw Error('Wall geometry or lighting invalid');
  const count=()=>[scene.meshes.length,scene.materials.length,scene.textures.length,scene.geometries.length];
  const before=count();
  const {buildHotelWalls}=await import('/lib/game/hotel-wall-scene.ts');
  const temporary=buildHotelWalls(scene);
  temporary.dispose();
  const after=count();
  if(before.some((n,i)=>n!==after[i])) throw Error('Wall disposal leaked scene resources');
  return {walls:report,disposeRestoresScene:true};
})()
